import { expect, test } from "bun:test";
import { join } from "node:path";
import polygonClipping from "polygon-clipping";
import { buildSolderStencil, type Ring, type StencilSide } from "../src/stencil";

// Frozen independent native KiCad paste plots. These are not generated by the
// code under test; a change in transforms, margins or corner shape must still
// agree with KiCad. Curves allow 5 micrometres for the 24-segment STL mesh.
const reference: {
  cases: { fixture: string; side: StencilSide; polygons: Ring[] }[];
} = await Bun.file(join(import.meta.dir, "fixtures/stencil-native-reference.json")).json();

function area(polys: polygonClipping.MultiPolygon): number {
  return polys.reduce(
    (total, poly) =>
      total +
      poly.reduce((sum, ring, i) => {
        const a = Math.abs(
          ring.reduce((s, [x, y], j) => {
            const next = ring[(j + 1) % ring.length]!;
            return s + x * next[1] - next[0] * y;
          }, 0) / 2,
        );
        return sum + (i === 0 ? a : -a);
      }, 0),
    0,
  );
}

function distance(p: number[], a: number[], b: number[]): number {
  const dx = b[0]! - a[0]!,
    dy = b[1]! - a[1]!;
  const len2 = dx * dx + dy * dy;
  const t = len2
    ? Math.max(0, Math.min(1, ((p[0]! - a[0]!) * dx + (p[1]! - a[1]!) * dy) / len2))
    : 0;
  return Math.hypot(p[0]! - a[0]! - t * dx, p[1]! - a[1]! - t * dy);
}

for (const ref of reference.cases) {
  test(`stencil matches native KiCad: ${ref.fixture} ${ref.side}.Paste`, async () => {
    const text = await Bun.file(
      join(import.meta.dir, "fixtures", `${ref.fixture}.kicad_pcb`),
    ).text();
    const built = buildSolderStencil(text, { side: ref.side });
    const expected = polygonClipping.union(...ref.polygons.map((p) => [p]));
    const actual = polygonClipping.union(...built.apertures.map((a) => [a.polygon]));
    expect(actual.length).toBe(expected.length);
    const intersection = polygonClipping.intersection(expected, actual);
    const union = polygonClipping.union(expected, actual);
    expect(area(intersection) / area(union)).toBeGreaterThan(0.998);
    // Check both directions: area alone can hide a narrow misplaced opening.
    for (const [from, to] of [
      [expected, actual],
      [actual, expected],
    ]) {
      const edges = to!.flatMap((poly) =>
        poly.flatMap((r) => r.slice(0, -1).map((a, i) => [a, r[i + 1]!] as const)),
      );
      let worst = 0;
      for (const p of from!.flat(2)) {
        worst = Math.max(worst, Math.min(...edges.map(([a, b]) => distance(p, a, b))));
      }
      expect(worst).toBeLessThan(0.005);
    }
  });
}
